/* thinking indicator for /ask feature */
.thinking-indicator {
	display: flex;
	align-items: center;
	padding: 10px;
	border-radius: 6px;
	background-color: rgb(233, 233, 233);
	max-width: fit-content;
	margin: 20px 0;
	color: #333;
}

.spinner {
	margin-right: 10px;
	color: #2f6fa7;
	animation: pulse 1.5s ease-in-out infinite;
}

.dots {
	display: inline-block;
	position: relative;
	width: 40px;
	height: 10px;
	margin-left: 5px;
}

.dots span {
	position: absolute;
	width: 6px;
	height: 6px;
	background-color: #2f6fa7;
	border-radius: 50%;
	animation: dots 1.5s infinite ease-in-out;
}

.dots span:nth-child(1) {
	left: 0px;
	animation-delay: 0s;
}

.dots span:nth-child(2) {
	left: 12px;
	animation-delay: 0.2s;
}

.dots span:nth-child(3) {
	left: 24px;
	animation-delay: 0.4s;
}

@keyframes pulse {
	0%, 100% {
		opacity: 0.4;
		transform: scale(1);
	}

	50% {
		opacity: 1;
		transform: scale(1.15);
	}
}

@keyframes dots {

	0%,
	80%,
	100% {
		transform: scale(0.8);
		opacity: 0.5;
	}

	40% {
		transform: scale(1.2);
		opacity: 1;
	}
}


