/* group home */
.grouphome-fit {
	max-width: 100%;
	max-height: 100%;
}

/* Desktop group-home section cards: each h4-led block (Group
   Information / Settings / Email Addresses / Integrations / Top
   Hashtags / Archived Messages / Subscription) sits in a subtle card
   so the page reads as grouped sections instead of one long flow. */
.grouphome-card {
	background: #fff;
	border: 1px solid #e5e8ec;
	border-radius: 8px;
	padding: 16px 20px;
	margin-bottom: 16px;
}
.grouphome-card > h4:first-child {
	margin-top: 0;
	margin-bottom: 12px;
	padding-bottom: 10px;
	border-bottom: 1px solid #eee;
	font-weight: 600;
}
body.dark-mode .grouphome-card {
	background: var(--dark-mode-primary-color);
	border-color: var(--dark-mode-divider);
}
body.dark-mode .grouphome-card > h4:first-child {
	border-bottom-color: var(--dark-mode-divider);
}

/* Inside each card: tighten the list typography, soften the icon
   colour (icons are decoration, not emphasis), and add subtle row
   spacing so items read as distinct entries instead of a wall. */
.grouphome-card ul.list-unstyled {
	margin-bottom: 0;
}
.grouphome-card ul.list-unstyled > li {
	padding: 6px 0;
	line-height: 1.5;
}
.grouphome-card ul.list-unstyled > li + li {
	border-top: 1px solid #f0f2f5;
}
.grouphome-card ul.list-unstyled > li > i.fa-fw {
	color: #8891a0;
	margin-right: 6px;
}
body.dark-mode .grouphome-card ul.list-unstyled > li + li {
	border-top-color: var(--dark-mode-divider);
}
body.dark-mode .grouphome-card ul.list-unstyled > li > i.fa-fw {
	color: #7a8390;
}

/* Group Email Addresses: two-column label/value grid so long emails
   don't wrap under their labels. Labels are muted; values are the
   actionable mailto links. */
.grouphome-email-list {
	display: grid;
	grid-template-columns: auto 1fr;
	column-gap: 14px;
	row-gap: 8px;
	margin: 0;
}
.grouphome-email-list dt {
	color: #6b7380;
	font-weight: 500;
	align-self: baseline;
	white-space: nowrap;
}
.grouphome-email-list dd {
	margin: 0;
	word-break: break-all;
}
body.dark-mode .grouphome-email-list dt {
	color: var(--dark-mode-light-text-color, #98a1ae);
}

/* Top Hashtags: flex-wrap grid of chips with the thread count baked
   in as a subtle secondary number inside each chip. Replaces the old
   vertical list-per-row layout. */
.grouphome-tags-list {
	display: flex;
	flex-wrap: wrap;
	gap: 6px;
}
.grouphome-tag-chip {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	padding: 4px 10px;
	border-radius: 14px;
	font-size: 13px;
	line-height: 1.3;
	text-decoration: none;
}
.grouphome-tag-chip:hover,
.grouphome-tag-chip:focus {
	filter: brightness(0.92);
	text-decoration: none;
}
.grouphome-tag-count {
	font-size: 11px;
	font-weight: 600;
	opacity: 0.85;
	padding: 1px 6px;
	background: rgba(0, 0, 0, 0.22);
	border-radius: 10px;
}

.grouphome-center {
	display: block;
	margin: auto;
}

/* Group home mobile cover hero: shallow 3:1 banner that bleeds
   edge-to-edge under the fixed navbar. The cover image is rendered
   at object-fit: contain so the full photo shows without cropping;
   off-aspect uploads letterbox with the page background. Mobile
   only — desktop uses the original centred .grouphome-fit image
   markup. */
.grouphome-hero {
	/* Bleed edge-to-edge on xs: counter the maincontent column's 5px
	   horizontal padding and cross the 5px gap that #maincontent
	   leaves under the fixed navbar so the image sits flush. */
	margin-left: -5px;
	margin-right: -5px;
	margin-top: -5px;
	position: relative;
	width: auto;
	aspect-ratio: 3 / 1;
	overflow: hidden;
	margin-bottom: 14px;
}
.grouphome-hero-img {
	position: relative;
	width: 100%;
	height: 100%;
	object-fit: contain;
	display: block;
}

/* group home mobile compact stats row: single-line member/topic/date
   summary between the hero and the tiles. */
.grouphome-stats {
	font-size: 13px;
	color: #707070;
	padding: 0 4px 10px;
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 0;
}
.grouphome-stat {
	white-space: nowrap;
}
.grouphome-stat i {
	margin-right: 3px;
}
.grouphome-stat-sep {
	color: #c8c8c8;
	margin: 0 6px;
}
body.dark-mode .grouphome-stats {
	color: var(--dark-mode-light-text-color);
}
body.dark-mode .grouphome-stat-sep {
	color: #555;
}

/* group home mobile hashtag chips: compact chip row, no counts. */
.grouphome-hashtags {
	margin: 14px 0 18px;
}
.grouphome-hashtags-head {
	display: flex;
	justify-content: space-between;
	align-items: baseline;
	font-size: 13px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.04em;
	color: #555;
	margin-bottom: 6px;
	padding: 0 4px;
}
.grouphome-hashtags-head a {
	font-size: 12px;
	font-weight: 400;
	text-transform: none;
	letter-spacing: 0;
}
.grouphome-hashtag-chip {
	display: inline-block;
	margin: 4px 4px 0 0;
	padding: 4px 10px;
	font-size: 13px;
	border-radius: 14px;
}
body.dark-mode .grouphome-hashtags-head {
	color: var(--dark-mode-light-text-color);
}

/* group home mobile tile grid: 4 compact square tiles per row.
   Overrides Bootstrap's .row negative margin to match the tighter
   per-tile column padding used below. */
.grouphome-tiles {
	margin: 12px -4px 18px;
}

/* group home mobile list (alternate layout; not currently rendered but
   retained for easy toggling from the tile grid). */
.grouphome-list {
	margin: 12px 0 18px;
	background: #fff;
	border-radius: 10px;
	overflow: hidden;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}
body.dark-mode .grouphome-list {
	background: var(--dark-mode-primary-color);
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}
.grouphome-row {
	display: flex;
	align-items: center;
	padding: 13px 14px;
	color: #333;
	text-decoration: none !important;
	border-top: 1px solid #eee;
	min-height: 48px;
}
.grouphome-row:first-child {
	border-top: 0;
}
.grouphome-row:hover,
.grouphome-row:focus,
.grouphome-row:active {
	background: #f2f5f9;
	color: #333;
}
body.dark-mode .grouphome-row {
	color: var(--dark-mode-text-color);
	border-top-color: var(--dark-mode-divider);
}
body.dark-mode .grouphome-row:hover,
body.dark-mode .grouphome-row:focus,
body.dark-mode .grouphome-row:active {
	background: var(--dark-mode-highlight-color);
	color: var(--dark-mode-text-color);
}
.grouphome-row-icon {
	font-size: 18px;
	color: #337ab7;
	margin-right: 14px;
	width: 22px;
	text-align: center;
}
body.dark-mode .grouphome-row-icon {
	color: #8cb4df;
}
.grouphome-row-label {
	flex: 1;
	font-size: 16px;
	font-weight: 500;
}
.grouphome-row-badge {
	background: #d9534f;
	color: #fff;
	padding: 1px 8px;
	border-radius: 10px;
	font-size: 12px;
	font-weight: 700;
	margin-left: 8px;
	min-width: 20px;
	text-align: center;
}
.grouphome-row-chevron {
	font-size: 12px;
	color: #c0c4ca;
	margin-left: 10px;
}
body.dark-mode .grouphome-row-chevron {
	color: #5a5e65;
}

/* Ensure no content hides behind the fixed bottom nav on the group
   home. The global #maincontent-column has padding-bottom:100px, but
   grouphome's body-height JS can reduce available space; add a little
   breathing room here on xs so the last visible element clears the
   nav + safe-area inset comfortably. */
@media (max-width: 767px) {
	#maincontent-column {
		padding-bottom: calc(110px + env(safe-area-inset-bottom));
	}
}

.grouphome-tile-col {
	padding-left: 4px;
	padding-right: 4px;
	margin-bottom: 8px;
}

.grouphome-tile {
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	padding: 10px 4px;
	text-align: center;
	background-color: #f5f5f5;
	color: #333;
	border-radius: 8px;
	text-decoration: none;
	position: relative;
	min-height: 74px;
}

.grouphome-tile:hover,
.grouphome-tile:focus,
.grouphome-tile:active {
	background-color: #e8e8e8;
	color: #333;
	text-decoration: none;
}

.grouphome-tile i {
	font-size: 20px;
	display: block;
	margin-bottom: 6px;
	color: #337ab7;
}

body.dark-mode .grouphome-tile i {
	color: #8cb4df;
}

.grouphome-tile-label {
	font-size: 12px;
	display: block;
	line-height: 1.2;
}

.grouphome-tile-badge {
	position: absolute;
	top: 4px;
	right: 6px;
	background-color: #d9534f;
	color: #fff;
	padding: 1px 6px;
	border-radius: 10px;
	font-size: 11px;
	font-weight: bold;
	min-width: 18px;
}

body.dark-mode .grouphome-tile {
	background-color: var(--dark-mode-primary-color);
	color: var(--dark-mode-text-color);
}

body.dark-mode .grouphome-tile:hover,
body.dark-mode .grouphome-tile:focus,
body.dark-mode .grouphome-tile:active {
	background-color: var(--dark-mode-highlight-color);
	color: var(--dark-mode-text-color);
}

/* Group home description: clamp long descriptions with a fade-out
   gradient and a "Show more" toggle. JS unhides the button only when
   the content actually overflows the clamp. */
.grouphome-desc-wrap {
	position: relative;
	margin-bottom: 12px;
}
.grouphome-desc {
	position: relative;
}
.grouphome-desc.clipped {
	max-height: 160px;
	overflow: hidden;
}
.grouphome-desc.clipped::after {
	content: "";
	position: absolute;
	left: 0;
	right: 0;
	bottom: 0;
	height: 48px;
	pointer-events: none;
	background: linear-gradient(to bottom, rgba(255, 255, 255, 0), #fff);
}
body.dark-mode .grouphome-desc.clipped::after {
	background: linear-gradient(to bottom, rgba(0, 0, 0, 0), var(--dark-mode-body-color));
}
.grouphome-desc.expanded {
	max-height: none;
	overflow: visible;
}
.grouphome-desc.expanded::after {
	display: none;
}
.grouphome-desc-toggle {
	background: none;
	border: 0;
	padding: 4px 0;
	color: #337ab7;
	font-weight: 500;
	cursor: pointer;
}
.grouphome-desc-toggle[hidden] {
	display: none;
}
body.dark-mode .grouphome-desc-toggle {
	color: #8cb4df;
}
.grouphome-desc-toggle .grouphome-desc-less,
.grouphome-desc.expanded ~ .grouphome-desc-toggle .grouphome-desc-more {
	display: none;
}
.grouphome-desc.expanded ~ .grouphome-desc-toggle .grouphome-desc-less {
	display: inline;
}

/* Recent Topics list on the group home page. Compact rows with the
   subject on the left and a short relative-time tag on the right. */
.grouphome-recent {
	margin-top: 16px;
	margin-bottom: 16px;
}
.grouphome-recent-head {
	display: flex;
	align-items: baseline;
	justify-content: space-between;
	margin-bottom: 6px;
