}
.grouphome-recent-link {
	font-size: 12px;
	text-transform: uppercase;
	letter-spacing: 0.5px;
}
.grouphome-recent-list {
	list-style: none;
	padding: 0;
	margin: 0;
}
.grouphome-recent-item {
	display: flex;
	align-items: baseline;
	gap: 10px;
	padding: 4px 0;
