}
.groupslist-mobsort .btn {
	white-space: nowrap;
}

/* Mobile-only row overrides for the groups table. */
@media (max-width: 767px) {
	#records.table-striped > tbody > tr > td,
	#records.table-striped > tbody > tr > th,
	#records.table-striped > tbody > tr {
