}

.groupslist-mobcell {
	white-space: normal;
}
.groupslist-mobrow {
	display: flex;
	align-items: flex-start;
	gap: 12px;
}
.groupslist-mobicon-wrap {
	position: relative;
	flex: 0 0 56px;
}
.groupslist-mobicon {
	width: 56px;
	height: 56px;
	display: block;
}
.groupslist-mobunread {
	position: absolute;
	top: -4px;
	right: -4px;
	background: #d9534f;
	color: #fff;
	padding: 1px 6px;
	border-radius: 10px;
	font-size: 11px;
	font-weight: bold;
	min-width: 18px;
	text-align: center;
	line-height: 16px;
}
.groupslist-mobbody {
	flex: 1;
	min-width: 0;
}
.groupslist-mobtitle {
	font-size: 16px;
	line-height: 1.25;
	margin-bottom: 2px;
}
.groupslist-mobrole {
	font-size: 10px;
	margin-left: 4px;
	vertical-align: 2px;
}
.groupslist-moblock {
	margin-left: 6px;
	color: #999;
}
.groupslist-mobdesc {
	font-size: 12px;
	color: #666;
	line-height: 1.35;
	margin: 2px 0 4px;
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
