}
.groupslist-mobpending {
	display: inline-block;
	margin-right: 4px;
}

/* /post page: sender user-chip on the left, "# Add Tags" button on
   the right. Subject line below takes the full width. */
.grouppost-sender-row {
	display: flex;
	flex-wrap: nowrap;
	justify-content: space-between;
	align-items: center;
	gap: 6px;
	width: 100%;
}
.grouppost-sender-row .dropdown {
	flex: 1 1 auto;
	min-width: 0;
}
.grouppost-sender-row .dropdown .user-chip {
	max-width: 100%;
}
.grouppost-sender-row .grouppost-tags-btn {
	flex: 0 0 auto;
}

/* Rounded corners on the TinyMCE editor wrapper so it feels like a
   contained card instead of a bare rectangle, at the same radius as the
   form controls around it. overflow:hidden keeps the toolbar's own
   corners clipped to the outer radius. */
.tox.tox-tinymce {
	border-radius: 10px;
	overflow: hidden;
}

/* On xs, tighten the gap between the Subject row and the editor. */
@media (max-width: 767px) {
	#postform .form-group + .tox.tox-tinymce {
		margin-top: 0;
	}
	#postform .form-group {
		margin-bottom: 8px;
	}
}

/* Shared user-identity chip. Used as the "From" selector on
   /post and /reply, the sender dropdown on /pendingmsg, and
   similar user-identity dropdowns elsewhere. Reads as a tappable
   control rather than an underlined link. */
.user-chip {
	display: inline-flex;
	align-items: center;
	padding: 4px 12px 4px 4px;
	border: 1px solid #ccc;
	border-radius: 20px;
	background: #fff;
	color: #333;
	text-decoration: none;
	max-width: 100%;
}
.user-chip:hover,
.user-chip:focus,
.user-chip:active {
	background: #f2f5f9;
	color: #333;
	text-decoration: none;
	border-color: #b8bdc4;
}
body.dark-mode .user-chip {
	background: var(--dark-mode-primary-color);
	color: var(--dark-mode-text-color);
	border-color: var(--dark-mode-divider);
}
body.dark-mode .user-chip:hover,
body.dark-mode .user-chip:focus {
	background: var(--dark-mode-highlight-color);
	color: var(--dark-mode-text-color);
}
.user-chip-inner {
	display: inline-flex;
	align-items: center;
	gap: 8px;
	min-width: 0;
}
.user-chip-avatar {
	width: 32px;
	height: 32px;
	border-radius: 50%;
	flex: 0 0 32px;
}
.user-chip-avatar-icon {
	font-size: 28px;
	color: #b8bdc4;
	line-height: 1;
}
.user-chip-name {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	max-width: 220px;
}
/* Non-interactive version: same avatar + name typography, but no
   border/background/hover. Used where a user is being displayed but
   has no associated dropdown. */
.user-chip-static {
	display: inline-flex;
	align-items: center;
	gap: 8px;
	min-width: 0;
}

/* /messages sticky-wiki alert: on xs, the multi-line wiki preview is
   collapsed behind a "📌 Pinned" chip that expands on tap. Desktop
   unchanged. */
.stickywiki-toggle {
	background: none;
	border: none;
	padding: 0;
	color: #337ab7;
	font-weight: 500;
	cursor: pointer;
}
.stickywiki-toggle i {
	margin-right: 4px;
}
.stickywiki-toggle-caret {
	transition: transform 0.15s ease;
}
.stickywiki-alert.open .stickywiki-toggle-caret {
	transform: rotate(180deg);
}
body.dark-mode .stickywiki-toggle {
	color: #8cb4df;
}
@media (max-width: 767px) {
	.stickywiki-alert {
		padding: 10px 28px 10px 14px;
	}
	.stickywiki-alert #stickywiki,
	.stickywiki-alert #readmorelink {
		display: none;
	}
	.stickywiki-alert.open #stickywiki,
	.stickywiki-alert.open #readmorelink {
		display: block;
		margin-top: 8px;
	}
}

/* /messages expanded view: hide subject-row on xs when the subject
   matches the previous message (thread continuation). */
.expanded-subject-dup {
	display: none;
}
@media (min-width: 768px) {
	.expanded-subject-dup {
		display: block;
	}
}

/* Footer strip at the bottom of an expanded-message card. Stretches
   to the card edges via negative margin; adds rounded bottom corners. */
.expanded-message-footer {
	margin-left: -10px;
	margin-right: -10px;
	margin-bottom: -10px;
	padding: 4px 10px 2px;
	border-bottom-left-radius: 4px;
	border-bottom-right-radius: 4px;
}

/* Reply / Like / More buttons under each message. Desktop shows icon
   + label; xs hides the label to keep the row compact. min-height of
   44px keeps the tap target comfortable on phones. All three buttons
   share the same inline-flex layout so they baseline-align. */
.msg-action {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	min-height: 44px;
	padding: 0 4px;
	line-height: 1;
}
.msg-action-count {
	font-size: 12px;
	opacity: 0.75;
}
/* Align the More dropdown with the other action buttons, but only on
   the variant that's actually visible at each breakpoint — overriding
   `display` on the hidden variant would break the wide/narrow swap. */
@media (min-width: 768px) {
	.msg-more-drop.dropdown-wide {
		display: inline-flex;
		align-items: center;
		gap: 6px;
		min-height: 44px;
		padding: 0 4px;
		line-height: 1;
	}
}
@media (max-width: 767px) {
	.msg-action-label {
		display: none;
	}
	.msg-action i {
		font-size: 18px;
	}
	.msg-more-drop.dropdown-narrow {
		display: inline-flex;
		align-items: center;
		min-height: 44px;
		padding: 0 4px;
		line-height: 1;
		/* font-size: 0 hides the button's text label on xs while
		   the icon, explicitly sized below, stays visible. The
		   dropdown template renders the label inline and we can't
		   easily wrap it in its own span to hidden-xs it. */
		font-size: 0;
	}
	.msg-more-drop.dropdown-narrow i {
		font-size: 18px;
	}
}

/* /message single-message page: on mobile, indent the subject header
   so it aligns with the user chip and body inside the card below,
   instead of hugging the viewport edge. */
@media (max-width: 767px) {
	.groupmessage-subject {
		padding-left: 11px;
	}
}


/* /messages expanded view: layout for subject row. Date/link float
   right on the subject row; the sender user-chip sits on its own
   row below, left-aligned. */
.expanded-subject-row {
	display: flex;
	align-items: baseline;
	gap: 8px;
}
.expanded-subject-row .subject {
	flex: 1 1 auto;
	min-width: 0;
	order: 1;
}
.expanded-subject-meta {
	flex: 0 0 auto;
	text-align: right;
	white-space: nowrap;
	order: 2;
}
.expanded-sender-row {
	margin-top: 6px;
}
/* On pages that omit the in-card subject (/topic, /message), the
   per-message meta (date + permalink) floats right in the sender row
   so the user-chip keeps the left edge. */
.expanded-sender-col {
	display: flex;
	align-items: baseline;
	gap: 8px;
}
.expanded-sender-col .dropdown,
.expanded-sender-col .user-chip-static {
	flex: 1 1 auto;
	min-width: 0;
	order: 1;
}
.expanded-sender-meta {
	flex: 0 0 auto;
	text-align: right;
	white-space: nowrap;
	order: 2;
}

/* Bold the subject on mobile so it's easy to spot vs the message body. */
@media (max-width: 767px) {
	.subject,
	body.dark-mode .subject {
		font-weight: 600;
	}
}

/* Message-subject hashtag pills: let them wrap under the subject on
   xs instead of overflowing horizontally. */
@media (max-width: 767px) {
	.subject {
		display: inline;
	}
	.subject .hashtag-position,
	.subject .hashtag-btn {
		display: inline-block;
		margin-top: 4px;
	}
}

/* /post page: moderator posting options. Always visible on desktop;
   on xs, collapsed behind a "Posting options" toggle so the page
   isn't cluttered for the common composer. */
.grouppost-options-toggle {
	display: none;
	background: none;
	border: none;
	padding: 8px 0;
	color: #337ab7;
	font-weight: 500;
	cursor: pointer;
}
.grouppost-options-toggle i {
	margin-right: 4px;
}
.grouppost-options-caret {
	transition: transform 0.15s ease;
}
.grouppost-options.open .grouppost-options-caret {
	transform: rotate(180deg);
}
body.dark-mode .grouppost-options-toggle {
	color: #8cb4df;
}
@media (max-width: 767px) {
	.grouppost-options-toggle {
		display: inline-flex;
		align-items: center;
	}
	.grouppost-options:not(.open) .grouppost-options-body {
		display: none;
	}
}

/* database table */
.dbtable {
	border-top: none;
	border-bottom: none;
	background-color: #FFF;
}

.event-dot {
	display: inline-block;
	width: 10px;
	height: 10px;
	border-radius: 5px;
}

.album-owner a {
	color: white;
}

/* mobile hamburger drawer */
.drawer {
	display: none;
}

.drawer-header {
	padding: 1.5rem;
	display: flex;
	justify-content: space-between;
	align-items: center;
	border-bottom: 1px solid #ddd;
}

.drawer-close {
	margin: 0;
	padding: 0;
	border: none;
	background-color: transparent;
	cursor: pointer;
	background-image: url("data:image/svg+xml,%0A%3Csvg width='15px' height='16px' viewBox='0 0 15 16' version='1.1' xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink'%3E%3Cg id='Page-1' stroke='none' stroke-width='1' fill='none' fill-rule='evenodd'%3E%3Cg id='2.-Menu' transform='translate(-15.000000, -13.000000)' stroke='%23000000'%3E%3Cg id='Group' transform='translate(15.000000, 13.521000)'%3E%3Cpath d='M0,0.479000129 L15,14.2971819' id='Path-3'%3E%3C/path%3E%3Cpath d='M0,14.7761821 L15,-1.24344979e-14' id='Path-3'%3E%3C/path%3E%3C/g%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
	width: 15px;
	height: 15px;
}

.drawer-wrapper {
	position: fixed;
	top: 0;
	right: 0;
	bottom: 0;
	height: 100%;
	width: 100%;
	max-width: 500px;
	z-index: 9999;
	overflow: auto;
	transition: transform 0.2s;
	will-change: transform;
	background-color: #fff;
	display: flex;
	flex-direction: column;
	-webkit-transform: translateX(103%);
	transform: translateX(103%);
	/* extra 3% because of box-shadow */
	-webkit-overflow-scrolling: touch;
	/* enables momentum scrolling in iOS overflow elements */
	box-shadow: 0 2px 6px #707070;
}

.drawer-wrapper-top {
	padding-top: max(0px, env(safe-area-inset-top));
}

.drawer-content {
	position: relative;
	overflow-x: hidden;
	overflow-y: auto;
	height: 100%;
	flex-grow: 1;
	padding: 1.5rem;
}

.drawer.is-active {
	display: inline;
}

.drawer.is-visible .drawer-wrapper {
	-webkit-transform: translateX(0);
	transform: translateX(0);
}

.drawer.is-visible .drawer-overlay {
	opacity: 0.5;
}

.drawer-overlay {
	position: fixed;
	top: 0;
	right: 0;
	bottom: 0;
	left: 0;
	width: 100%;
	z-index: 200;
	opacity: 0;
	transition: opacity 0.2s;
	will-change: opacity;
	background-color: #000;
	-webkit-user-select: none;
	-moz-user-select: none;
	-ms-user-select: none;
	user-select: none;
}

.drawer-left .drawer-wrapper {
	left: 0;
	right: auto;
	-webkit-transform: translate3d(-100%, 0, 0);
	transform: translate3d(-100%, 0, 0);
}

.drawer-bottom .drawer-wrapper {
	top: auto;
	right: 0;
	bottom: 0;
	left: 0;
	height: auto;
	width: 100%;
	max-height: 500px;
	max-width: none;
	-webkit-transform: translateY(103%);
	transform: translateY(103%);
	/* extra 3% because of box-shadow */
}

body.app .navbar-fixed-top {
	padding-top: max(0px, env(safe-area-inset-top));
	/*padding-bottom: max(20px, env(safe-area-inset-bottom));*/
}

/* attachment display */
.attachment-box {
	border: 1px solid #f5f5f5;
	margin: 10px;
	text-align: center;
	height: 100px;
	width: 150px;
	position: relative;
	transition: background-color 0.2s ease;
}

.attachment-box:hover {
	background-color: #f5f5f5;
}

.attachment-icon,
.attachment-image {
	transition: opacity 0.2s ease;
}

.attachment-icon {
	font-size: 40px;
	margin-top: 15px;
}

.attachment-image {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	object-fit: cover;
}

/* On phones, when an attachment row contains any image, switch to a
   responsive 2-column flex grid with taller cells so photos are
   actually viewable instead of cramped 150x100 thumbnails. Two
   images split 50/50; three or more wrap into rows of two (a lone
   third item stays at 50% width instead of stretching). */
@media (max-width: 767px) {
	.attachment-row:has(.attachment-image) {
		display: flex;
		flex-wrap: wrap;
		gap: 4px;
		margin-left: 0;
		margin-right: 0;
	}
	/* Bootstrap 3's .row clearfix pseudo-elements become zero-width
	   flex items that offset the first child by one gap. Suppress
	   them so the grid aligns at the row's left edge. */
	.attachment-row:has(.attachment-image)::before,
	.attachment-row:has(.attachment-image)::after {
		display: none;
	}
	.attachment-row:has(.attachment-image) > a {
		flex: 1 1 calc(50% - 4px);
		min-width: 0;
		padding: 0;
		display: block;
	}
	.attachment-row:has(.attachment-image) > a > .attachment-box {
		width: 100%;
		height: 180px;
		margin: 0;
	}
}

.attachment-box:hover .attachment-icon,
.attachment-box:hover .attachment-image {
	opacity: 0;
}

.attachment-name,
.attachment-name-hover {
	background-color: #f5f5f5;
	padding: 5px;
	position: absolute;
	bottom: 0;
	left: 0;
	right: 0;
	font-size: 12px;
	transition: opacity 0.2s ease;
}

.attachment-name {
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.attachment-name-hover {
	opacity: 0;
}

.attachment-box:hover .attachment-name {
	opacity: 0;
}

.attachment-box:hover .attachment-name-hover {
	opacity: 1;
}

.delete-checkbox {
	position: absolute;
	top: 5px;
	right: 5px;
}

/* files move tree */
.tree,
.tree ul {
	margin: 0;
	padding: 0;
	list-style: none
}

.tree ul {
	margin-left: 1em;
	position: relative
}

.tree ul ul {
	margin-left: .5em
}

.tree ul:before {
	content: "";
	display: block;
	width: 0;
	position: absolute;
	top: 0;
	bottom: 0;
	left: 0;
	border-left: 1px solid
}

.tree li {
	margin: 0;
	padding: 0 1em;
	line-height: 2em;
	font-weight: 700;
	position: relative
}

.tree ul li:before {
	content: "";
	display: block;
	width: 10px;
	height: 0;
	border-top: 1px solid;
	margin-top: -1px;
	position: absolute;
	top: 1em;
	left: 0
}

.tree ul li:last-child:before {
	background: #fff;
	height: auto;
	top: 1em;
	bottom: 0
}

.treeindicator {
	margin-right: 5px;
}

.tree li a {
	text-decoration: none;
}

.tree li button,
.tree li button:active,
.tree li button:focus {
	text-decoration: none;
	border: none;
	background: transparent;
	margin: 0px 0px 0px 0px;
	padding: 0px 0px 0px 0px;
	outline: 0;
}

.maincontent-column {
	height:100%;
}
.maincontent-chat-column {
	position: absolute;
	top: calc(55px + env(safe-area-inset-top));
	bottom: env(safe-area-inset-bottom);
	right: 0;
	left: 235px;
	width: calc(100vw - 235px);
	padding-right:0px;
	margin-bottom: 0px !important;
}

/* chat */
#chat-container {
	display: flex;
	flex-direction: column;
	width: 100%;
	height: calc(100% - 0px);
	margin: 0 auto;
	box-sizing: border-box;
	font-size: 17px;
}

@media (max-width: 991.98px) {
	/* adjust margins for narrow screens */
	.container,
	.container-fluid {
		padding-left: 5px;
		padding-right: 5px;
	}

	.row {
		margin-left: -5px;
		margin-right: -5px;
	}

	/* Bring every Bootstrap column to the same 5px gutter as col-xs-12
	   so side-by-side halves (e.g., Start Date + Start Time) line up
	   with the full-width fields above and below them. Without this,
	   col-xs-6 inherits Bootstrap's default 15px padding and the half-
	   width inputs get inset 10px further than their siblings. */
	.col-xs-1, .col-xs-2, .col-xs-3, .col-xs-4, .col-xs-5, .col-xs-6,
	.col-xs-7, .col-xs-8, .col-xs-9, .col-xs-10, .col-xs-11, .col-xs-12,
	.narrow-padding {
		padding-left: 5px;
		padding-right: 5px;
	}

	#maincontent {
		position: absolute;
		top: calc(55px + env(safe-area-inset-top));
		bottom: 80px;
		right: 0;
		left: 0;
		/* COMMENTED OUT for now because it causes HTMX to not handle infinite scrolling correctly. It causes a jump back to the top of the page. */
		/*overflow-y: auto !important;*/
	}

	/* added this in when we commented out overflow-y above. */
	#maincontent-column {
		padding-bottom: 100px;
	}

	.maincontent-chat-column {
		top: 0px !important;
		left: 0px !important;
		width: 100% !important;
		padding-bottom: 0px !important;
		padding-left: 0px;
	}

	#chat-container {
		height: 100%;
	}
}

#chat-messages {
	flex: 1;
	overflow-y: auto;
	padding: 10px;
	display: flex;
	flex-direction: column;
}

#chat-messages-wrapper {
	display: flex;
	flex-direction: column;
	align-items: flex-end;
}

#chat-preview {
	padding: 10px;
	align-items: center;
}

/* chat video thumbnails are wrapped in an <a> that opens the video modal;
   the default underline on the anchor shows up as a stray underscore next
   to the image since the anchor only contains whitespace + an <img>. */
a.video-link, a.video-link:hover, a.video-link:focus {
	text-decoration: none;
}

/* File attachment card in the composer preview (before sending) and in
   delivered messages (after). Both use the same inner layout: icon on the
   left, filename + size stacked in the middle, download chevron on the
   right for delivered ones. */
.thumbnail.chat-preview-file {
	display: flex;
	align-items: center;
	gap: 10px;
	padding: 10px 12px;
	min-width: 220px;
	max-width: 320px;
	background: #f5f5f5;
	border-radius: 10px;
}
.chat-preview-file-icon {
	font-size: 26px;
	color: #337ab7;
	flex-shrink: 0;
}
.chat-preview-file-meta {
	flex: 1;
	min-width: 0;
}
.chat-preview-file-name {
	font-size: 14px;
	font-weight: 500;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.chat-preview-file-size {
	font-size: 12px;
	color: #888;
}

/* In-message version: link, so it needs to override default anchor styling
   and provide a pressed/hover state. */
a.chat-file-card {
	display: flex;
	align-items: center;
	gap: 10px;
	padding: 10px 12px;
	min-width: 0;
	max-width: 100%;
	background: rgba(0, 0, 0, 0.06);
	border-radius: 10px;
	text-decoration: none !important;
	color: inherit;
}

/* Wrapper span around chat media is inline by default, which lets a
   flex child (e.g. .chat-file-card with a long filename) overflow its
   parent bubble. Make it a block with max-width:100% so the card's
   own max-width:100% actually constrains to the bubble. */
[id^="msgpayload-"] {
	display: block;
	max-width: 100%;
	min-width: 0;
}
a.chat-file-card:hover,
a.chat-file-card:focus {
	background: rgba(0, 0, 0, 0.10);
	text-decoration: none !important;
}
.chat-message.sent a.chat-file-card {
	background: rgba(255, 255, 255, 0.15);
	color: #fff;
}
.chat-message.sent a.chat-file-card:hover,
.chat-message.sent a.chat-file-card:focus {
	background: rgba(255, 255, 255, 0.22);
}
.chat-file-card-icon {
	font-size: 26px;
	color: inherit;
	flex-shrink: 0;
}
.chat-file-card-meta {
	flex: 1;
	min-width: 0;
}
.chat-file-card-name {
	font-size: 14px;
	font-weight: 500;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.chat-file-card-size {
	font-size: 12px;
	opacity: 0.7;
}
.chat-file-card-action {
	font-size: 16px;
	opacity: 0.6;
	flex-shrink: 0;
}
body.dark-mode .thumbnail.chat-preview-file {
	background: #2b2b2b;
	color: #e9ecef;
}
body.dark-mode a.chat-file-card {
	background: rgba(255, 255, 255, 0.08);
}
body.dark-mode a.chat-file-card:hover,
body.dark-mode a.chat-file-card:focus {
	background: rgba(255, 255, 255, 0.14);
}

/* video in chat reply preview: thumbnail with a play-icon overlay so the user
   can tell at a glance they've attached a video instead of an image. */
.thumbnail.chat-preview-video {
	position: relative;
}
.chat-preview-video-play {
	position: absolute;
	top: 50%;
	left: 50%;
	transform: translate(-50%, -50%);
	font-size: 42px;
	color: rgba(255, 255, 255, 0.9);
	text-shadow: 0 1px 6px rgba(0, 0, 0, 0.6);
	pointer-events: none;
}

.chat-form {
	display: flex;
	padding: 10px;
	align-items: center;
	background-color: #f8f8f8;
}

.chat-button-color {
	background-color: #f8f8f8
}

.chat-message-content-wrapper {
	display: flex;
	flex-direction: row;
	max-width: 100%;
	min-width: 0;
}

/* Chat video viewer. Edge-to-edge black on mobile (iOS-photos feel),
   aspect-fit and centered on desktop. Replaces the Bootstrap-default
   modal chrome so a portrait video inside a square-ish dialog no
   longer leaves empty white margins or gets clipped off-screen. */
.modal.video-modal {
	padding: 0 !important;
}
.modal.video-modal.in,
.modal.video-modal.show {
	display: flex !important;
}
.video-modal-dialog {
	margin: 0 auto;
	width: 100%;
	max-width: 100vw;
	/* dvh tracks the iOS URL-bar collapse; plain vh leaves the viewer
	   taller than visible and clips the bottom of the video. */
	height: 100dvh;
	padding: 0;
	pointer-events: auto;
}
.video-modal-content {
	background: #000;
	border: none;
	border-radius: 0;
	height: 100%;
	display: flex;
	flex-direction: column;
	box-shadow: none;
	position: relative;
}
.video-modal-body {
	flex: 1 1 auto;
	display: flex;
	align-items: center;
	justify-content: center;
	overflow: hidden;
	min-height: 0;
	background: #000;
}
.video-modal-player {
	width: 100%;
	height: 100%;
	max-height: 100%;
	max-width: 100%;
	object-fit: contain;
	background: #000;
	outline: none;
}
/* Floating circular close button in the top-right corner. 44px tap
   target meets the iOS HIG minimum; safe-area-inset keeps it below
   notches and the iOS status bar. */
.video-modal-close {
	position: absolute;
	top: calc(12px + env(safe-area-inset-top));
	right: calc(12px + env(safe-area-inset-right));
	width: 44px;
	height: 44px;
	border: none;
	border-radius: 50%;
	background: rgba(0, 0, 0, 0.55);
	color: #fff;
	font-size: 18px;
	line-height: 1;
	cursor: pointer;
	z-index: 10;
	display: flex;
	align-items: center;
	justify-content: center;
	opacity: 0.9;
	transition: opacity 0.15s, background-color 0.15s;
	-webkit-touch-callout: none;
	-webkit-user-select: none;
	user-select: none;
}
.video-modal-close:hover,
.video-modal-close:focus {
	opacity: 1;
	background: rgba(0, 0, 0, 0.75);
	color: #fff;
	outline: none;
}
/* Bottom metadata strip: sender · time  [Download] */
.video-modal-meta {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
	padding: 10px 16px calc(10px + env(safe-area-inset-bottom));
	background: rgba(0, 0, 0, 0.72);
	color: rgba(255, 255, 255, 0.92);
	font-size: 13px;
	flex-shrink: 0;
}
.video-modal-meta-info {
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.video-modal-meta-sender {
	font-weight: 600;
}
.video-modal-meta-sep {
	opacity: 0.6;
	margin: 0 4px;
}
.video-modal-meta-date {
	opacity: 0.85;
}
.video-modal-download {
	border: none;
	background: rgba(255, 255, 255, 0.14);
	color: #fff;
	border-radius: 6px;
	padding: 8px 12px;
	font-size: 13px;
	display: inline-flex;
	align-items: center;
	gap: 6px;
	flex-shrink: 0;
	cursor: pointer;
	transition: background-color 0.15s;
	min-height: 36px;
}
.video-modal-download:hover,
.video-modal-download:focus {
	background: rgba(255, 255, 255, 0.24);
	color: #fff;
	outline: none;
}

/* Desktop: centred viewer with rounded corners, not fullscreen.
   Dimensions are set inline by JS on `loadedmetadata` to match the
   video's natural aspect ratio — otherwise a portrait clip in a
   fixed-size box leaves black bars on either side. Caps below apply
   before metadata loads or as an upper bound if JS can't size. */
@media (min-width: 768px) {
	.modal.video-modal.in,
	.modal.video-modal.show {
		align-items: center;
		justify-content: center;
	}
	.video-modal-dialog {
		width: auto;
		max-width: 95vw;
		height: auto;
		max-height: 95dvh;
		margin: 0 auto;
	}
	.video-modal-content {
		width: auto;
		height: auto;
		max-width: min(960px, 95vw);
		max-height: min(720px, 95dvh);
		border-radius: 12px;
		overflow: hidden;
	}
	.video-modal-body {
		min-height: 0;
	}
}

/* Audio voice-message bubble. A subtle translucent container holds
   the play button and a waveform. Colours adapt to the surrounding
   chat-message context (received / sent / dark mode) so the controls
   always contrast with the bubble behind them. Waveform bars use
   currentColor so a single `color` override per context retints them.
   Lives in the main stylesheet (not an ExtraHeader <style>) so the
   rules are still present after HTMX partial swaps into /chat/. */
.audio-waveform-container {
	background-color: rgba(0, 0, 0, 0.05);
	border-radius: 18px;
	padding: 6px 12px 6px 6px;
	color: #6b6b6b;
}
.dark-mode .audio-waveform-container {
	background-color: rgba(255, 255, 255, 0.08);
	color: #bfbfbf;
}
/* Sent (blue) bubble: the default blue button would vanish into the
   bubble. Flip the palette — white pill button with a blue play icon,
   translucent-white waveform bars. */
.chat-message.sent .audio-waveform-container {
	background-color: rgba(255, 255, 255, 0.15);
	color: rgba(255, 255, 255, 0.85);
}
.audio-waveform {
	border-radius: 4px;
	height: 36px;
}
/* Clip duration shown to the right of the waveform. Inherits `color`
   from the container (retinted per bubble context), so contrast stays
   correct on sent/received/dark bubbles. */
.audio-duration {
	font-size: 12px;
	font-variant-numeric: tabular-nums;
	opacity: 0.8;
	flex-shrink: 0;
}
.audio-play-button {
	width: 36px;
	height: 36px;
	border-radius: 50%;
	border: none;
	background-color: #337ab7;
	color: #fff;
	cursor: pointer;
	display: flex;
	align-items: center;
	justify-content: center;
	font-size: 13px;
	flex-shrink: 0;
	transition: background-color 0.2s;
}
/* The fa-play glyph has whitespace to its right inside the bounding
   box, so flex-centring leaves the triangle visually shifted left.
   Nudge it right for optical centring. Undone when the icon class
   switches to fa-pause (symmetric glyph). */
.audio-play-button .fa-play {
	transform: translateX(1px);
}
.audio-play-button:hover {
	background-color: #2a6496;
}
.audio-play-button:active {
	background-color: #1f4e78;
}
.dark-mode .audio-play-button {
	background-color: #4a90e2;
}
.dark-mode .audio-play-button:hover {
	background-color: #3a7bc8;
}
.chat-message.sent .audio-play-button {
	background-color: #fff;
	color: #337ab7;
}
.chat-message.sent .audio-play-button:hover {
	background-color: #eef3f8;
}
.chat-message.sent .audio-play-button:active {
	background-color: #dde7f2;
}

.chat-message {
	position: relative;
	margin-bottom: 10px;
	display: flex;
	flex-direction: row;
	max-width: 80%;
}

.chat-message-content {
	display: flex;
	flex-direction: column;
	padding: 5px;
	border-radius: 10px;
	word-break: break-word;
	max-width: 100%;
	min-width: 0;
}


/* Ask answer-bubble actions: icon-only buttons beside the bubble, named by
   aria-label and shown by tooltips. nowrap keeps them from stacking in the
   flex row. */
.chat-message-actions {
	align-self: flex-start;
	white-space: nowrap;
	padding: 5px 0 0 8px;
}

.chat-message-actions a,
.chat-message-actions .ask-action {
	color: #999;
	margin-right: 8px;
}

.chat-message-actions .ask-action {
	padding: 0;
	border: 0;
	background: none;
}

.chat-message-actions a:hover,
.chat-message-actions .ask-action:hover {
	color: #337ab7;
}

/* Ask keeps the question field focusable but read-only while an answer is
   generated; dim it the way a disabled field would look. */
#chat-message-input[aria-disabled="true"] {
	opacity: 0.65;
}

/* Bubble content is markdown-rendered: without this, the final paragraph's
   bottom margin adds to the bubble padding and makes bubbles bottom-heavy. */
.chat-message-content p:last-child {
	margin-bottom: 0;
}

.chat-message.received .chat-message-content {
	background-color: rgb(233, 233, 233);
}

.chat-message.received .chat-message-content a {
	text-decoration: underline;
}

.chat-message.sent .chat-message-content {
	background-color: #337ab7;
	color: rgb(224, 231, 243);
}

.chat-message.sent .chat-message-content a {
	color: rgb(224, 231, 243);
	text-decoration: underline;
}

.chat-message.received {
	align-self: flex-start;
}

.chat-message.date .chat-message-content {
	background-color: rgb(233, 233, 233);
}

.chat-message.date {
	align-self: center;
}

.chat-message.sent {
	align-self: flex-end;
}

.chat-message.emojimargin {
	margin-bottom: 30px;
}

/* Typing indicator: strip above the composer that shows "X is typing…"
   with three pulsing dots. Rendered once per user; automatically removes
   itself after the typing event stops arriving. */
.chat-typing-indicator {
	padding: 4px 12px;
	font-size: 12px;
	color: #888;
	background: transparent;
}
/* The region stays rendered while empty so screen readers announce the
   typing line when it is added; it takes no space until then. */
.chat-typing-indicator:empty {
	padding: 0;
}
.chat-typing-row {
	display: flex;
	align-items: center;
	gap: 6px;
	padding: 2px 0;
}
.chat-typing-name {
	font-style: italic;
}
.chat-typing-dots {
	display: inline-flex;
	gap: 3px;
	align-items: center;
}
.chat-typing-dots span {
	width: 5px;
	height: 5px;
	border-radius: 50%;
	background: #888;
	opacity: 0.35;
	animation: chat-typing-bounce 1.2s infinite ease-in-out both;
}
.chat-typing-dots span:nth-child(2) { animation-delay: 0.15s; }
.chat-typing-dots span:nth-child(3) { animation-delay: 0.30s; }
@keyframes chat-typing-bounce {
	0%, 80%, 100% { transform: translateY(0); opacity: 0.35; }
	40%           { transform: translateY(-3px); opacity: 1; }
}

/* Emoji picker: anchored above the composer. Kept compact on mobile so it
   doesn't swallow the chat history, and wide-open on desktop. */
#chat-emoji-picker {
	position: absolute;
	bottom: 60px;
	left: 8px;
	right: 8px;
	max-height: 260px;
	overflow-y: auto;
	background: #fff;
	border: 1px solid #ddd;
	border-radius: 8px;
	box-shadow: 0 -2px 8px rgba(0, 0, 0, 0.08);
	padding: 8px;
	z-index: 20;
}
@media (min-width: 768px) {
	#chat-emoji-picker {
		left: auto;
		right: 10px;
		width: 340px;
	}
}
.emoji-picker-label {
	font-size: 11px;
	text-transform: uppercase;
	color: #888;
	letter-spacing: 0.04em;
	margin: 6px 2px 4px;
}
.emoji-picker-grid {
	display: grid;
	grid-template-columns: repeat(auto-fill, minmax(36px, 1fr));
	gap: 2px;
}
.emoji-picker-btn {
	background: transparent;
	border: 0;
	padding: 4px;
	font-size: 22px;
	line-height: 1;
	border-radius: 4px;
	cursor: pointer;
}
.emoji-picker-btn:hover,
.emoji-picker-btn:focus {
	background: #eef3fa;
}
/* The fill alone is 1.1:1; keyboard focus also takes the focus ring
   (groupsio-bs5.css defines --gio-focus-ring-color, light and dark). */
.emoji-picker-btn:focus:not(:focus-visible) {
	outline: none;
}
.emoji-picker-btn:focus-visible {
	outline: 2px solid var(--gio-focus-ring-color, #2a6496);
	outline-offset: -2px;
}
body.dark-mode #chat-emoji-picker {
	background: #2b2b2b;
	border-color: #444;
}
body.dark-mode .emoji-picker-btn:hover,
body.dark-mode .emoji-picker-btn:focus {
	background: #3b4657;
}

/* Swipe-to-reply indicator: a small reply arrow revealed in the message
   gutter as the bubble slides left during a horizontal swipe. Goes solid
   blue once the user has swiped far enough to trigger the reply. */
.chat-swipe-reply-hint {
	position: absolute;
	right: 8px;
	top: 50%;
	transform: translateY(-50%);
	font-size: 18px;
	color: #999;
	opacity: 0;
	pointer-events: none;
	transition: color 100ms ease;
}
.chat-swipe-reply-hint.armed {
	color: #337ab7;
}

/* Grouped: this message follows another message from the same user within
   the group-gap window. Tighten spacing and hide the repeated header
   (avatar/username) and trailing timestamp so a run of messages reads as a
   single cluster instead of a stack of isolated bubbles. */
.chat-message.grouped {
	margin-bottom: 2px;
}
/* A grouped message that also has tapbacks still needs the full 30px gutter
   so the tapback chip doesn't overlap the next bubble in the group. */
.chat-message.grouped.emojimargin {
	margin-bottom: 30px;
}
/* File-card bubbles have a solid-color card that starts right at the bubble's
   top edge, so any incoming tapback from the message above visually sits
   on top of the card. Give them a little top margin to push them clear.
   :has() is widely supported in current browsers; it no-ops where it isn't. */
.chat-message:has(a.chat-file-card) {
	margin-top: 6px;
}
.chat-message.emojimargin + .chat-message:has(a.chat-file-card) {
	margin-top: 14px;
}
.chat-message.grouped .chat-profile-picture-wrapper {
	visibility: hidden;
}
/* The repeated sender and time are hidden from sight only, so screen
   readers still hear who sent each message and when (same rules as
   Bootstrap's .visually-hidden). */
.chat-message.received.grouped .chat-message-content > span[id^="msguser-"],
.chat-message.sent.grouped .chat-message-content > span[id^="msguser-"],
.chat-message.grouped .chat-timestamp-sent,
.chat-message.grouped .chat-timestamp-received {
	position: absolute !important;
	width: 1px !important;
	height: 1px !important;
	padding: 0 !important;
	margin: -1px !important;
	overflow: hidden !important;
	clip: rect(0, 0, 0, 0) !important;
	white-space: nowrap !important;
	border: 0 !important;
}

.chat-profile-picture {
	border-radius: 6px;
	width: 40px;
	height: 40px;
	min-width: 40px;
	min-height: 40px;
	margin-right: 10px;
	align-self: flex-end;
	object-fit: cover;
}

.chat-message.show-picture .chat-profile-picture {
	display: block;
}

.chat-profile-picture-wrapper {
	display: flex;
	width: 50px;
	min-width: 50px;
	align-self: flex-end;
}

.chat-timestamp-sent {
	font-size: 12px;
	margin-top: 3px;
	align-self: flex-end;
}

.chat-timestamp-received {
	font-size: 12px;
	margin-top: 3px;
	align-self: flex-end;
	color: rgb(152, 150, 150);
}

.chat-emoji-box {
	position: absolute;
	display: flex;
	background-color: #ececec;
	border-radius: 10px;
	padding: 3px 7px;
	bottomXX: -20px;
	right: 0;
	z-index: 10;
}

.chat-emoji-box a {
	text-decoration: none !important;
}

.sent .chat-emoji-box {
	background-color:#337ab7;
}

.chat-emoji {
	font-size: 1.4rem;
	margin-right: 5px;
}

#chat-unread-counter {
	position: absolute;
	bottom: 70px;
	right: 20px;
	display: none;
	justify-content: center;
	align-items: flex-start;
	z-index: 1000;
	padding: 0;
	border: 0;
	background: none;
}

.chat-connection-status {
	padding: 6px 12px;
	font-size: 14px;
	background-color: #fcf8e3;
	color: #6b5326;
}
.chat-connection-status.chat-send-error {
	background-color: #f8d7da;
	color: #842029;
}
.chat-connection-status:empty {
	padding: 0;
}

#chat-unread-badge {
	position: absolute;
	background-color: #337ab7;
	top: -13px;
	/* Adjust the position of the badge */
	left: 50%;
	/* Center the badge horizontally */
	transform: translateX(-50%);
	/* Adjust the position to account for the badge's width */
	z-index: 10;
	/* Make sure the badge appears above the icon */
}

.upper-wrapper {
	/* New class */
	display: block;
	width: 100%;
}

#chat-message-input {
	flex: 1;
	padding: 5px;
	border-radius: 10px;
	border: 1px solid #ccc;
	overflow: hidden;
	min-height: 34px;
	outline: none;
}

#chat-username-popup {
	position: absolute;
	max-height: 240px;
	overflow-y: auto;
	bottom: 50px;
	left: 10px;
	right: 10px;
	z-index: 1000;
	background: #fff;
	border: 1px solid #ddd;
	border-radius: 8px;
	box-shadow: 0 -2px 8px rgba(0, 0, 0, 0.08);
	padding: 4px;
}
@media (min-width: 768px) {
	#chat-username-popup {
		right: auto;
		width: 360px;
	}
}
body.dark-mode #chat-username-popup {
	background: #2b2b2b;
	border-color: #444;
}
.chat-mention-item {
	display: flex;
	align-items: center;
	gap: 10px;
	padding: 6px 8px;
	border: 0 !important;
	border-radius: 6px;
	background: transparent !important;
}
.chat-mention-item:hover,
.chat-mention-item:focus,
.chat-mention-item.active {
	background: #eef3fa !important;
	color: inherit !important;
}
body.dark-mode .chat-mention-item:hover,
body.dark-mode .chat-mention-item:focus,
body.dark-mode .chat-mention-item.active {
	background: #3b4657 !important;
}
.chat-mention-avatar {
	width: 32px;
	height: 32px;
	border-radius: 50%;
	background: #eee;
	display: flex;
	align-items: center;
	justify-content: center;
	overflow: hidden;
	flex-shrink: 0;
	color: #888;
}
.chat-mention-avatar img {
	width: 100%;
	height: 100%;
	object-fit: cover;
}
body.dark-mode .chat-mention-avatar {
	background: #3b4657;
	color: #aaa;
}
.chat-mention-names {
	display: flex;
	flex-direction: column;
	min-width: 0;
	flex: 1;
}
.chat-mention-display {
	font-size: 14px;
	font-weight: 500;
	overflow: hidden;
	text-overflow: ellipsis;
