/*                                  Dropzone                                  */
/* -------------------------------------------------------------------------- */
.dropzone {
	position: relative;
	background-color: #fff;
	border: 0;
	background-color: transparent;
	border-radius: 0.375rem;
}

.dropzone.dropzone-has-default .dz-message {
	border-color: transparent;
	-webkit-transition: all 0.2s ease-in-out;
	transition: all 0.2s ease-in-out;
}

.dropzone.dropzone-has-default .dz-message:hover {
	background-color: rgba(0, 0, 0, 0.5);
}

.dropzone .dz-preview {
	min-height: auto;
	margin: 0px;
}

.dropzone .dz-remove {
	position: absolute;
	right: 0.5rem;
	top: 0.5rem;
	color: #fff;
	z-index: 1000;
	cursor: pointer;
	opacity: 0;
	width: 2rem;
	height: 2rem;
	line-height: 2rem;
}

.dropzone .dz-remove * {
	cursor: pointer;
}

.dropzone .dz-message {
	position: relative;
	padding: 5rem 2rem;
	margin: 0;
	border: 2px dashed var(--light-mode-divider);
	border-radius: 0.375rem;
}

.dropzone.dropzone-single.dz-max-files-reached .dz-message {
	background-color: rgba(0, 0, 0, 0.5);
	color: #fff;
	opacity: 0;
	-webkit-transition: all 0.2s ease-in-out;
	transition: all 0.2s ease-in-out;
	border-color: transparent;
}

.dropzone.dropzone-single.dz-max-files-reached .dz-remove {
	opacity: 1;
}

.dropzone.dropzone-single.dz-max-files-reached:hover .dz-message,
.dropzone.dropzone-single.dz-max-files-reached:focus .dz-message {
	opacity: 1;
}

.dropzone .dz-preview-single {
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	bottom: 0;
	margin: 0;
}

.dropzone .dz-preview-single:hover {
	z-index: auto;
}

.dropzone .dz-preview-single .dz-preview-cover {
	position: absolute;
	height: 100%;
	width: 100%;
	border: 0 !important;
	overflow: hidden;
}

.dropzone .dz-preview-single .dz-preview-cover .dz-errormessage {
	position: absolute;
	left: 0;
	bottom: 0;
}

.dropzone .dz-preview-single .dz-preview-img {
	width: 100%;
	height: 100%;
	-o-object-fit: cover;
	object-fit: cover;
	border-radius: 0.375rem;
}

.dropzone.dropzone-multiple {
	border: 0;
	background: transparent;
}

.dropzone.dropzone-multiple .dz-message {
	padding: 4rem 2rem;
	border: 2px dashed var(--light-mode-divider);
	border-radius: 0.375rem;
}

