/* /feed stories bar: horizontal-scrolling row of group circles. Only
   rendered when the user has 3+ active groups. */
.feed-group-circles {
	overflow-x: auto;
	white-space: nowrap;
	padding: 6px 0 10px;
	-webkit-overflow-scrolling: touch;
	-ms-overflow-style: none;
	scrollbar-width: none;
}
.feed-group-circles::-webkit-scrollbar {
	display: none;
}
.feed-group-circle {
	display: inline-block;
	width: 76px;
	margin: 0 4px;
	text-align: center;
	vertical-align: top;
	text-decoration: none;
	color: inherit;
}
.feed-group-circle-iconwrap {
	position: relative;
	display: inline-block;
	margin-bottom: 4px;
}
.feed-group-circle-img {
	width: 56px;
	height: 56px;
	display: block;
}
.feed-group-circle-unread .feed-group-circle-img {
	box-shadow: 0 0 0 2px #fff, 0 0 0 4px #337ab7;
}
body.dark-mode .feed-group-circle-unread .feed-group-circle-img {
	box-shadow: 0 0 0 2px var(--dark-mode-bg), 0 0 0 4px #8cb4df;
}
.feed-group-circle-badge {
	position: absolute;
	top: -2px;
	right: -2px;
	/* #cd4845 keeps the white count at 4.6:1 */
	background: #cd4845;
	color: #fff;
	padding: 1px 6px;
	border-radius: 10px;
	font-size: 11px;
	font-weight: bold;
	min-width: 18px;
	text-align: center;
	line-height: 16px;
	border: 2px solid #fff;
}
body.dark-mode .feed-group-circle-badge {
	border-color: var(--dark-mode-bg);
}
.feed-group-circle-label {
	font-size: 11px;
	line-height: 1.2;
	height: 28px;
	overflow: hidden;
	text-overflow: ellipsis;
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
	word-break: break-word;
}

/* /feed section headers: icon + title + VIEW ALL link. Replaces the
   ad-hoc feed-border + inline-styled <span>s used previously. */
.feed-section-header {
	display: flex;
	justify-content: space-between;
	align-items: baseline;
	padding: 10px 0 6px;
	border-bottom: 1px solid #eee;
	margin-top: 8px;
}
