}
.feed-section-title {
	margin: 0;
	font-size: 15px;
	font-weight: 600;
	color: #333;
}
body.dark-mode .feed-section-title {
	color: var(--dark-mode-text-color);
}
.feed-section-title i {
	color: #337ab7;
	margin-right: 6px;
	width: 18px;
	text-align: center;
}
body.dark-mode .feed-section-title i {
	color: #8cb4df;
}
.feed-section-link {
	font-size: 11px;
	letter-spacing: 0.5px;
	text-transform: uppercase;
	white-space: nowrap;
}

/* /feed topic rows: let hashtags wrap under the date instead of
   being hidden on xs. */
.feed-topic-meta {
	white-space: normal;
	text-align: right;
	vertical-align: top;
}
.feed-topic-meta-inner {
	font-size: 12px;
	text-align: right;
	white-space: nowrap;
}
.feed-topic-tags {
	margin-top: 4px;
	white-space: normal;
}
.feed-topic-tags .hashtag-position {
	margin-left: 4px;
	margin-top: 2px;
	display: inline-block;
	/* Match the topic list's pills; the badge's 0.75em would otherwise
	   scale down from the 12px meta column. */
	font-size: 12px;
}

/* /feed empty state shown when the user has no groups with recent
   activity. */
.feed-empty {
	text-align: center;
	padding: 40px 20px;
}
.feed-empty-icon {
	font-size: 48px;
	color: #c0c4ca;
	margin-bottom: 16px;
